INSERT IGNORE INTO material_content_blob (
    id, owner_type, owner_key, content_sha256, byte_size, detected_mime,
    original_object_key, status
) VALUES (
    #{id}, #{ownerType}, #{ownerKey}, #{contentSha256}, #{byteSize}, #{detectedMime},
    #{originalObjectKey}, #{status}
)

mapper.select:
SELECT * FROM material_content_blob
WHERE owner_type = #{ownerType} AND owner_key = #{ownerKey}
  AND content_sha256 = #{contentSha256} AND byte_size = #{byteSize}
FOR UPDATE

mapper.insert:
INSERT INTO material (
    id, owner_type, owner_key, kind, display_name, retention_class, origin_conversation_id,
    lifecycle_state, lifecycle_generation, latest_version_id, last_meaningful_activity_at, expires_at
) VALUES (
    #{id}, #{ownerType}, #{ownerKey}, #{kind}, #{displayName}, #{retentionClass},
    #{originConversationId}, #{lifecycleState}, #{lifecycleGeneration}, #{latestVersionId},
    #{lastMeaningfulActivityAt}, #{expiresAt}
)

mapper.update:
UPDATE material
SET retention_class = 'RETAINED', expires_at = NULL, lifecycle_generation = #{newGeneration}
WHERE id = #{materialId} AND owner_type = #{ownerType} AND owner_key = #{ownerKey}
  AND lifecycle_state = 'ACTIVE' AND retention_class = 'TEMPORARY'
  AND lifecycle_generation = #{expectedGeneration}

mapper.insert:
INSERT INTO material_version (
    id, material_id, owner_key, version_no, content_blob_id, content_sha256,
    declared_mime, detected_mime, byte_size, page_count, ingest_state
) VALUES (
    #{id}, #{materialId}, #{ownerKey}, #{versionNo}, #{contentBlobId}, #{contentSha256},
    #{declaredMime}, #{detectedMime}, #{byteSize}, #{pageCount}, #{ingestState}
)

INSERT INTO material_processing_revision (
    id, version_id, revision_no, fingerprint, state, stage, progress,
    parser_version, cleaner_version, chunk_schema_version, ocr_version, vlm_schema_version,
    excluded_pages_json
) VALUES (
    #{id}, #{versionId}, #{revisionNo}, #{fingerprint}, #{state}, #{stage}, #{progress},
    #{parserVersion}, #{cleanerVersion}, #{chunkSchemaVersion}, #{ocrVersion}, #{vlmSchemaVersion},
    #{excludedPagesJson}
)
